<?php
require_once 'functions.php'; require_module_access('payslip');
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['delete_id'])) { $id=(int)$_POST['delete_id']; $stmt=mysqli_prepare($mysqli,'DELETE FROM payslips WHERE id = ?'); mysqli_stmt_bind_param($stmt,'i',$id); if(mysqli_stmt_execute($stmt)){$_SESSION['flash_success']='Slip gaji berhasil dihapus.';}else{$_SESSION['flash_error']='Slip gaji gagal dihapus.';} header('Location: payslips_list.php'); exit; }
$search=trim($_GET['search']??''); $period=trim($_GET['period']??''); $where=[]; if($search!==''){ $safe=mysqli_real_escape_string($mysqli,$search); $where[]="(payslip_no LIKE '%$safe%' OR employee_no LIKE '%$safe%' OR employee_name LIKE '%$safe%' OR employee_level LIKE '%$safe%')"; } if(preg_match('/^\d{4}-\d{2}$/',$period)){ $safe=mysqli_real_escape_string($mysqli,$period); $where[]="DATE_FORMAT(salary_period, '%Y-%m') = '$safe'"; } $payslips=mysqli_query($mysqli,'SELECT * FROM payslips'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY salary_period DESC, id DESC');
$success=$_SESSION['flash_success']??'';$error=$_SESSION['flash_error']??'';unset($_SESSION['flash_success'],$_SESSION['flash_error']);include 'header.php';
?>
<div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-3"><h3 class="mb-0">Daftar Slip Gaji</h3><a href="payslips_create.php" class="btn btn-primary"><i class="fas fa-plus mr-1"></i>Buat Slip Gaji</a></div><?php if($success): ?><div class="alert alert-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="card"><div class="card-body"><form class="form-row mb-3" method="get"><div class="col-md-4"><input name="search" class="form-control" placeholder="Cari slip atau karyawan" value="<?= htmlspecialchars($search) ?>"></div><div class="col-md-3"><input name="period" type="month" class="form-control" value="<?= htmlspecialchars($period) ?>"></div><div class="col-auto"><button class="btn btn-outline-primary"><i class="fas fa-search"></i></button></div><?php if($search!==''||$period!==''): ?><div class="col-auto"><a class="btn btn-outline-secondary" href="payslips_list.php">Reset</a></div><?php endif; ?></form><div class="table-responsive"><table class="table table-bordered table-hover mb-0"><thead class="thead-light"><tr><th>No.</th><th>Nomor Slip</th><th>Periode</th><th>Karyawan</th><th>Level / Jabatan</th><th>Metode</th><th>Invoice</th><th class="text-right">Total Neto</th><th>Tanggal Terbit</th><th class="text-center">Aksi</th></tr></thead><tbody><?php $no=1; while($payslip=mysqli_fetch_assoc($payslips)): ?><tr><td><?= $no++ ?></td><td><?= htmlspecialchars($payslip['payslip_no']) ?></td><td><?= date('F Y',strtotime($payslip['salary_period'])) ?></td><td><strong><?= htmlspecialchars($payslip['employee_name']) ?></strong><br><small class="text-muted"><?= htmlspecialchars($payslip['employee_no']) ?></small></td><td><?= htmlspecialchars($payslip['employee_level']) ?></td><td><span class="badge badge-<?= ($payslip['salary_method'] ?? 'invoice') === 'custom' ? 'info' : 'primary' ?>"><?= ($payslip['salary_method'] ?? 'invoice') === 'custom' ? 'Custom' : 'By Invoice' ?></span></td><td><?= (int) $payslip['invoice_count'] ?></td><td class="text-right">Rp <?= number_format($payslip['net_salary'],0,',','.') ?></td><td><?= date('d/m/Y',strtotime($payslip['issued_date'])) ?></td><td class="text-center"><a class="btn btn-sm btn-info" target="_blank" href="payslips_print.php?id=<?= $payslip['id'] ?>"><i class="fas fa-print"></i></a><a class="btn btn-sm btn-warning" href="payslips_edit.php?id=<?= $payslip['id'] ?>"><i class="fas fa-edit"></i></a><form method="post" class="d-inline" onsubmit="return confirm('Hapus slip gaji ini?');"><input type="hidden" name="delete_id" value="<?= $payslip['id'] ?>"><button class="btn btn-sm btn-danger"><i class="fas fa-trash"></i></button></form></td></tr><?php endwhile; ?></tbody></table></div></div></div></div>
<?php include 'footer.php'; ?>
